"""Adorama listing category inventory.

Normalized from the Adorama XML category sitemap
(https://www.adorama.com/UnifySiteMaps/Category.xml), captured 2026-10-01 UTC
against the US storefront through the project-wide ScrapeOps proxy.

1079 crawlable `/l/<Department>/<Category>/...` URLs across 11 departments.

Depth-1 department landing pages (`/l/Photography`, `/l/Audio`, ...) are CMS landing
nodes: they hydrate `pageInfo.pageType == "bcmsSitePage"` with no product grid, so they
are deliberately excluded. Depth-2+ nodes hydrate
`pageInfo.pageType == "listPage"` with 24 SSR products per page.

Inventory keys are the full `/l/` path slug (never the bare label) because Adorama
reuses labels across branches -- e.g. `Microphone Cases` exists under both
`Audio/Audio-Bags-and-Cases` and `Audio/Studio-and-Recording`, and `Tripods and
Supports` exists at two depths inside `Photography`. Keying on the path keeps all
1079 URLs addressable.
"""

from __future__ import annotations

ADORAMA_BASE_URL = "https://www.adorama.com"

# Adorama's Next.js list pages serve a fixed 24 products per page.
ADORAMA_PAGE_SIZE = 24

