def flatten_categories() -> list[dict[str, object]]:
    """Return every crawlable category as a flat `-a category=` selection."""
    return [
        dict(metadata)
        for inventory in ADORAMA_CATEGORY_INVENTORY.values()
        for metadata in inventory.values()
    ]


ADORAMA_CATEGORIES = flatten_categories()
